            // Input slab incl. halo: x[((r * iw_t) + col) * AK_CA + c], r < ih_t, col < iw_t.
            const int8_t *x = aie::load_buffer(x_t, {oh0 * AK_S, ow0 * AK_S, 0}, {ih_t, iw_t, AK_CA});
            // Output tile: y[(oh * ow_t + ow) * oc_t + oc].
