            //         x[((oh * AK_S + kh) * iw_t + ow * AK_S + kw) * AK_CA + c] * w[((oc * AK_KH + kh) * AK_KW + kw) *
            //         AK_CA + c]
            //   y[(oh * ow_t + ow) * oc_t + oc] = the layer's epilogue of acc (its parameters, see the header)
            (void)x;
            (void)y;
            aie::release(x_t);
            aie::commit(y_t);
